export interface NoteDictionaryEntry {
  en: string;
  pl: string;
  imageUrl?: string;
  category?: string;
}

const PL_CHARS: Record<string, string> = {
  "ą": "a", "ć": "c", "ę": "e", "ł": "l", "ń": "n", "ó": "o", "ś": "s", "ź": "z", "ż": "z",
};

// Normalizacja nazwy: transliteracja polskich znaków + slug.
export function slugifyNote(name: string): string {
  return name
    .toLowerCase().replace(/[ąćęłńóśźż]/g, (m) => PL_CHARS[m] || m)
    .replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

