export function translateNote(enName: string): { pl: string; imageUrl?: string; category?: string } {
  const key = slugifyNote(enName);
  const entry = notesDictionary[key];
  if (entry) return { pl: entry.pl, imageUrl: entry.imageUrl, category: entry.category };
  return { pl: enName };
}

// Dopasowuje nazwę nuty (po angielsku lub po polsku) do wpisu w słowniku,
// aby zawsze móc wyświetlić obrazek.
const byPolishName = (() => {
  const map: Record<string, NoteDictionaryEntry> = {};
  for (const entry of Object.values(notesDictionary)) {
    const plKey = slugifyNote(entry.pl);
    if (plKey && !map[plKey]) map[plKey] = entry;
  }
  return map;
})();

// Klucze posortowane od najkrótszych — używane do dopasowania prefiksowego.
const byPolishKeys = Object.keys(byPolishName).sort((a, b) => a.length - b.length);

// Warianty nazw (głównie polskie nazwy nut z Fragrantica) -> klucz kanoniczny słownika.
const noteAliases: Record<string, string> = {
  "cytryna-sycylijska": "lemon",
  "gardenia-tahitanska": "gardenia",
  "jasmin-wodny": "jasmine",
  "wanilia-madagaskarska": "vanilla",
  "nuty-morskie": "marine",
  "nuty-wodne": "aquatic",
  "lisc-paczuli": "patchouli",
  "lisc-cytryny": "petitgrain",
  "bursztyn-ambra": "amber",
  "drzewo-gwajakowe": "guaiac-wood",
  "tamaryndowiec": "tamarind",
};

export function resolveNoteImage(name: string): string | undefined {
  if (!name) return undefined;
  const key = slugifyNote(name);
  const entry = notesDictionary[key] || byPolishName[key];
  if (entry?.imageUrl) return entry.imageUrl;
  const aliasKey = noteAliases[key];
  if (aliasKey) {
    const aliasEntry = notesDictionary[aliasKey];
    if (aliasEntry?.imageUrl) return aliasEntry.imageUrl;
  }
  // 1) Dopasowanie prefiksowe: np. „Goździk” -> „gozdzik-kwiat”, „gozdziki-przyprawa”.
  for (const k of byPolishKeys) {
    if (k.startsWith(key)) return byPolishName[k]?.imageUrl || undefined;
  }
  // 2) Dopasowanie po jakości w nawiasie: „Goździk (przyprawa)” -> „gozdziki-przyprawa”.
  const paren = name.match(/\(([^()]+)\)/);
  if (paren) {
    const q = slugifyNote(paren[1]);
    if (q) {
      const suffixKey = byPolishKeys.find((k) => k.endsWith(`-${q}`));
      if (suffixKey) return byPolishName[suffixKey]?.imageUrl || undefined;
    }
    const baseKey = slugifyNote(name.replace(/\([^()]+\)/g, " "));
    if (baseKey && baseKey !== key) {
      const baseEntry = notesDictionary[baseKey] || byPolishName[baseKey] || notesDictionary[noteAliases[baseKey]];
      if (baseEntry?.imageUrl) return baseEntry.imageUrl;
    }
  }
  // 3) Dopasowanie po usunięciu wiodących przydawek geograficznych/rodzajowych:
  //    „Sycylijska mandarynka” -> „mandarynka”, „Egipski jaśmin” -> „jasmin”.
  const tokens = key.split("-");
  for (let i = 1; i < tokens.length; i++) {
    const suffixKey = tokens.slice(i).join("-");
    const suffixEntry = notesDictionary[suffixKey] || byPolishName[suffixKey];
    if (suffixEntry?.imageUrl) return suffixEntry.imageUrl;
  }
  // 4) Dopasowanie po usunięciu końcowych przydawek geograficznych/rodzajowych:
  //    „Cytryna sycylijska” -> „cytryna”, „Wanilia madagaskarska” -> „wanilia”.
  for (let i = tokens.length - 1; i > 0; i--) {
    const prefixKey = tokens.slice(0, i).join("-");
    const prefixEntry = notesDictionary[prefixKey] || byPolishName[prefixKey];
    if (prefixEntry?.imageUrl) return prefixEntry.imageUrl;
  }
  return undefined;
}

export function getAllNotes(): NoteDictionaryEntry[] {
  return Object.values(notesDictionary);
}

